"""Exploratory charts computed from the saved CSV files."""

from __future__ import annotations

import pandas as pd
import plotly.graph_objects as go
import streamlit as st

from src.config import CLASS_ORDER, FEATURE_SPECS, TARGET_COLUMN
from src.ui.common import CLASS_COLORS, apply_chart, load_primary, load_robustness, note, pretty_feature


def render_dataset_summary() -> None:
    st.info(
        "Provenance: both tables were generated by this project's code. "
        "Public extension pages informed the feature meanings. They did not supply these rows."
    )
    primary = load_primary()
    robust = load_robustness()
    st.write(
        f"Primary table: {len(primary):,} rows and {primary.shape[1]} columns. "
        f"Robustness table: {len(robust):,} rows. "
        f"Input features: {len(FEATURE_SPECS)}."
    )
    counts = primary[TARGET_COLUMN].astype(str).value_counts().reindex(CLASS_ORDER)
    figure = go.Figure(
        go.Bar(
            x=CLASS_ORDER,
            y=counts.to_numpy(),
            marker_color=[CLASS_COLORS[label] for label in CLASS_ORDER],
            text=[f"{int(value):,}" for value in counts],
            textposition="outside",
        )
    )
    apply_chart(figure, "Simulated risk classes in the primary file", "Class", "Inspections")
    st.plotly_chart(figure, width="stretch")
    shares = ", ".join(f"{label} {counts[label] / len(primary):.1%}" for label in CLASS_ORDER)
    note(
        f"The primary classes are {shares}. "
        "They are tertiles of a noisy score computed from the recorded measurements, so the near-balance is a property of that rule, not a survey of lawns."
    )
    missing = primary.isna().mean().sort_values(ascending=False)
    missing = missing[missing > 0]
    miss_figure = go.Figure(go.Bar(x=missing.index.map(pretty_feature), y=missing.values, marker_color="#2F6F4E"))
    apply_chart(miss_figure, "Missing laboratory fields in the primary file", "", "Fraction missing")
    miss_figure.update_layout(yaxis_tickformat=".0%")
    st.plotly_chart(miss_figure, width="stretch")
    note(
        "Only pH and the three nutrient columns are allowed to be missing. "
        "The plotted fractions are computed from the CSV. Unknown does not mean a healthy measurement."
    )


def render_dataset_details() -> None:
    primary = load_primary()
    robust = load_robustness()
    numeric = [name for name, spec in FEATURE_SPECS.items() if spec["kind"] == "numeric"]
    categorical = [name for name, spec in FEATURE_SPECS.items() if spec["kind"] == "categorical"]
    chosen = st.selectbox("Numeric feature", options=numeric, format_func=pretty_feature)
    hist = go.Figure()
    for label in CLASS_ORDER:
        values = pd.to_numeric(primary.loc[primary[TARGET_COLUMN] == label, chosen], errors="coerce").dropna()
        hist.add_trace(go.Histogram(x=values, name=label, marker_color=CLASS_COLORS[label], opacity=0.65, nbinsx=30))
    apply_chart(hist, f"{pretty_feature(chosen)} by simulated class", FEATURE_SPECS[chosen]["unit"], "Inspections")
    hist.update_layout(barmode="overlay")
    st.plotly_chart(hist, width="stretch")
    means = primary.groupby(TARGET_COLUMN)[chosen].mean().reindex(CLASS_ORDER)
    note(
        "Class means for this feature: "
        + ", ".join(f"{label} {means[label]:.2f}" for label in CLASS_ORDER)
        + ". Overlap is expected. A separated histogram would mean that one feature almost determines the label."
    )

    category = st.selectbox("Categorical feature", options=categorical, format_func=pretty_feature)
    share = primary.groupby([category, TARGET_COLUMN]).size().unstack(fill_value=0).reindex(columns=CLASS_ORDER)
    share = share.div(share.sum(axis=1), axis=0)
    cat_figure = go.Figure()
    for label in CLASS_ORDER:
        cat_figure.add_bar(name=label, x=share.index.astype(str), y=share[label], marker_color=CLASS_COLORS[label])
    apply_chart(cat_figure, f"Class mix within {pretty_feature(category)}", "", "Share of rows")
    cat_figure.update_layout(barmode="stack", yaxis_tickformat=".0%")
    st.plotly_chart(cat_figure, width="stretch")
    note("Each bar sums to 100% of that category. These shares are computed from the generated CSV.")

    numeric_frame = primary[numeric].apply(pd.to_numeric, errors="coerce")
    correlation = numeric_frame.corr(numeric_only=True)
    heat = go.Figure(
        data=go.Heatmap(
            z=correlation.to_numpy(),
            x=[pretty_feature(name) for name in correlation.columns],
            y=[pretty_feature(name) for name in correlation.index],
            zmin=-1,
            zmax=1,
            colorscale=[[0, "#8C3A3A"], [0.5, "#F7F5F2"], [1, "#2F6F4E"]],
            hovertemplate="%{y} and %{x}: %{z:.2f}<extra></extra>",
        )
    )
    apply_chart(heat, "Pearson correlations among numeric inputs", "", "")
    heat.update_yaxes(autorange="reversed")
    st.plotly_chart(heat, width="stretch")
    rain_moisture = float(numeric_frame["rainfall_7d_mm"].corr(numeric_frame["soil_moisture_pct"]))
    note(
        f"Seven-day rainfall and soil moisture correlate at {rain_moisture:.2f} in the primary file. "
        "The generator builds that association in. A correlation is not a field cause."
    )

    compare = go.Figure()
    for frame, name, color in ((primary, "Primary", "#2F6F4E"), (robust, "Robustness", "#C4B49A")):
        class_share = frame[TARGET_COLUMN].astype(str).value_counts(normalize=True).reindex(CLASS_ORDER)
        compare.add_bar(name=name, x=CLASS_ORDER, y=class_share.to_numpy(), marker_color=color)
    apply_chart(compare, "Class mix after the robustness shift", "Simulated class", "Share of rows")
    compare.update_layout(barmode="group", yaxis_tickformat=".0%")
    st.plotly_chart(compare, width="stretch")
    temp_shift = float(robust["temperature_c"].mean() - primary["temperature_c"].mean())
    rain_shift = float(robust["rainfall_7d_mm"].mean() - primary["rainfall_7d_mm"].mean())
    note(
        f"Mean temperature is {temp_shift:+.1f} °C on the robustness file relative to the primary file, "
        f"and mean seven-day rainfall is {rain_shift:+.1f} mm. "
        "The robustness file uses a different seed and the primary file's frozen score cutoffs. It is not a resample of the test set."
    )
